const paths={grid:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4z M13 6a3 3 0 0 1 3-3h5v16h-4a4 4 0 0 0-4 2',quiz:'M9 3h6v3H9z M9 4H5v17h14V4h-4 M8 11l1 1 2-2 M13 11h3 M8 16l1 1 2-2 M13 16h3',folder:'M3 7V4h6l3 3h9v13H3z M7 12h10 M7 16h6',chart:'M4 3v18h17 M8 16v-4 M13 16V7 M18 16V9',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4 M12 17h.01',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',search:'M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15 M16 16l5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',more:'M5 12h.01 M12 12h.01 M19 12h.01',trending:'M3 17l6-6 4 4 8-10 M15 5h6v6',check:'M20 6 9 17l-5-5',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',award:'M16 8a4 4 0 1 0-8 0 4 4 0 0 0 8 0 M8 12l-2 9 6-3 6 3-2-9',template:'M3 3h7v18H3z M14 3h7v7h-7z M14 14h7v7h-7z'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.folder}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const navItems=[['Overview','grid'],['User management','users','248'],['Training management','book'],['Assessments','quiz'],['Content library','folder'],['Reports & analytics','chart']];
const $=id=>document.getElementById(id);const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialCourses=[{id:1,name:'Leadership essentials',category:'Professional development',enrolled:128,progress:76,status:'Published',color:'#f1eef9',icon:'book',lessons:12},{id:2,name:'Information security awareness',category:'Compliance & security',enrolled:246,progress:92,status:'Published',color:'#edf4fb',icon:'shield',lessons:8},{id:3,name:'Effective communication',category:'Soft skills',enrolled:84,progress:61,status:'Published',color:'#fff3e9',icon:'users',lessons:10},{id:4,name:'Onboarding: getting started',category:'Employee onboarding',enrolled:52,progress:34,status:'Published',color:'#eef7f3',icon:'award',lessons:6},{id:5,name:'Customer success fundamentals',category:'Customer experience',enrolled:96,progress:100,status:'Completed',color:'#f2effa',icon:'book',lessons:9},{id:6,name:'Advanced project management',category:'Professional development',enrolled:0,progress:0,status:'Draft',color:'#edf4fb',icon:'template',lessons:14}];
let courses;try{courses=JSON.parse(localStorage.getItem('aa-courses'))||initialCourses}catch{courses=initialCourses}let page=1,chartMode='participation',activeView='Overview';const pageSize=4;
const activities=[{initials:'PS',name:'Priya Sharma',action:'completed a training',course:'Leadership essentials',time:'12 minutes ago'},{initials:'RM',name:'Rahul Mehta',action:'published a new quiz',course:'Information security · Final assessment',time:'38 minutes ago'},{initials:'AK',name:'Alex Kumar',action:'added 12 new learners',course:'Marketing team',time:'1 hour ago'},{initials:'ND',name:'Neha Desai',action:'uploaded new content',course:'Effective communication · Module 3',time:'2 hours ago'}];
function renderNav(){ $('nav').innerHTML=navItems.map(([name,i,badge])=>`<a href="#${name.toLowerCase().replaceAll(' ','-')}" class="${activeView===name?'active':''}">${icon(i)}<span>${name}</span>${badge?`<span class="nav-badge">${badge}</span>`:''}</a>`).join('') }
function renderMetrics(){const period=+$('period').value;const factor=period===7?.26:period===90?2.8:1;const items=[['Total learners',Math.round(248* (period===90?1.18:period===7?.85:1)).toLocaleString(),'12.4%','users'],['Active trainings',String(courses.filter(c=>c.status==='Published').length+20),'8.2%','book'],['Assessments taken',Math.round(1286*factor).toLocaleString(),'18.6%','quiz'],['Average score',period===7?'85.1%':period===90?'81.6%':'84.2%','4.2%','award']];$('metrics').innerHTML=items.map(([label,n,g,i])=>`<article class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(i)}</span></div><div class="metric-number">${n}</div><div class="metric-bottom"><span class="trend">↗ ${g}</span><span>vs. previous period</span></div></article>`).join('');const total=Math.round(1842*factor);const pct=period===7?81:period===90?72:78;$('donut-value').innerHTML=`${pct}<span>%</span>`;document.querySelector('.ring-progress').style.strokeDasharray=`${503*pct/100} 503`;$('completed').textContent=Math.round(total*pct/100).toLocaleString();$('progress').textContent=Math.round(total*(95-pct)/100).toLocaleString();$('not-started').textContent=Math.round(total*.05).toLocaleString();renderChart()}
function renderChart(){const period=+$('period').value;const total=Math.round((chartMode==='participation'?1842:1437)*(period===7?.26:period===90?2.8:1));$('chart-total').textContent=total.toLocaleString();document.querySelector('.chart-summary>span:nth-child(2)').textContent=chartMode==='participation'?'total enrollments':'total completions';$('chart-legend').textContent=chartMode==='participation'?'Enrollments':'Completions';const current=chartMode==='participation'?'M42 130 C66 130 67 103 91 103 S126 119 142 110 S162 57 188 67 S222 89 239 71 S270 100 285 98 S315 64 333 54 S366 70 384 62 S407 43 428 43 S467 65 487 49 S516 13 546 14':'M42 140 C67 140 70 120 91 120 S126 130 142 115 S168 101 188 100 S222 117 239 93 S270 97 285 78 S315 82 333 72 S366 89 384 73 S407 65 428 62 S467 67 487 45 S516 38 546 32';const labels=period===7?['Oct 7','Oct 8','Oct 9','Oct 10','Oct 11','Oct 12','Oct 13']:period===90?['Jul 15','Jul 30','Aug 14','Aug 29','Sep 13','Sep 28','Oct 13']:['Sep 14','Sep 19','Sep 24','Sep 29','Oct 4','Oct 9','Oct 13'];$('chart').innerHTML=`<svg viewBox="0 0 570 195" preserveAspectRatio="none" role="img" aria-label="${chartMode==='participation'?'Enrollments':'Completions'} trend for last ${period} days"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#f04461" stop-opacity=".13"/><stop offset="100%" stop-color="#f04461" stop-opacity="0"/></linearGradient></defs>${[20,65,110,155].map((y,i)=>`<line x1="42" y1="${y}" x2="550" y2="${y}" stroke="#edf0f4" stroke-dasharray="3 4"/><text x="4" y="${y+4}">${[300,200,100,0][i]}</text>`).join('')}<path d="${current} L546 155 L42 155Z" fill="url(#area)"/><path d="M42 137 C66 137 75 145 91 132 S126 133 142 131 S171 107 188 113 S218 126 239 105 S269 124 285 115 S315 97 333 100 S363 110 384 98 S409 101 428 87 S466 91 487 76 S519 78 546 57" stroke="#c8ced8" fill="none" stroke-width="1.5" stroke-dasharray="4 5"/><path d="${current}" fill="none" stroke="#ef3654" stroke-width="2.6" stroke-linecap="round"/>${labels.map((l,i)=>`<text x="${42+i*84}" y="181" text-anchor="${i===0?'start':i===6?'end':'middle'}">${l}</text>`).join('')}</svg>`}
const quickItems=[['User management','248 learners','users'],['Training management','24 active trainings','book'],['Question bank','1,240 questions','quiz'],['Assessments','86 assessments','check'],['Content library','152 resources','folder'],['Reports & analytics','Explore insights','chart']];
$('quick-grid').innerHTML=quickItems.map(([name,sub,i])=>`<button class="quick-card" data-module="${name}"><span class="quick-icon">${icon(i)}</span><span><strong>${name.replace(' management','').replace(' & analytics','')}</strong><small>${sub}</small></span></button>`).join('');
function filtered(){const term=$('search').value.toLowerCase(),status=$('status-filter').value;return courses.filter(c=>(c.name+' '+c.category).toLowerCase().includes(term)&&(status==='all'||c.status===status))}
function renderCourses(){const rows=filtered();const pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,pages);$('course-count').textContent=courses.length;const slice=rows.slice((page-1)*pageSize,page*pageSize);$('course-rows').innerHTML=slice.length?slice.map(c=>`<tr><td><button class="course-name row-more" data-course="${c.id}"><span class="course-icon" style="background:${c.color}">${icon(c.icon)}</span><span style="text-align:left">${esc(c.name)}<small>${esc(c.category)}</small></span></button></td><td>${c.enrolled}</td><td><div class="progress-cell"><span class="progress-track"><i style="width:${c.progress}%"></i></span>${c.progress}%</div></td><td><span class="status ${c.status.toLowerCase()}">${c.status}</span></td><td><button class="row-more" data-course="${c.id}" aria-label="View ${esc(c.name)}">${icon('more')}</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No trainings match your search.</td></tr>';$('table-count').textContent=rows.length?`Showing ${(page-1)*pageSize+1}–${Math.min(page*pageSize,rows.length)} of ${rows.length} trainings`:'0 trainings';$('page-number').textContent=page;$('previous').disabled=page===1;$('next').disabled=page===pages}
function feedHTML(list){return list.map(a=>`<div class="feed-item"><span class="feed-avatar">${esc(a.initials)}</span><div class="feed-body"><strong>${esc(a.name)}</strong> ${esc(a.action)}<span class="course-ref">${esc(a.course)}</span><time>${esc(a.time)}</time></div></div>`).join('')}
function renderFeed(){$('activity-feed').innerHTML=feedHTML(activities.slice(0,4))}
function showDialog(title,body){$('dialog-content').innerHTML=`<div class="dialog-top"><h2>${esc(title)}</h2><button class="dialog-close" aria-label="Close dialog">×</button></div>${body}`;$('dialog').showModal();document.querySelector('.dialog-close').onclick=()=>$('dialog').close()}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');setTimeout(()=>$('toast').classList.remove('visible'),3500)}
function courseDetail(id){const c=courses.find(c=>c.id===+id);if(!c)return;showDialog(c.name,`<p>${esc(c.category)} · ${c.lessons} lessons · <span class="status ${c.status.toLowerCase()}">${c.status}</span></p><div class="detail-stats"><div><strong>${c.enrolled}</strong>Enrolled learners</div><div><strong>${c.progress}%</strong>Completion</div><div><strong>${c.lessons}</strong>Lessons</div></div><p>${c.status==='Draft'?'Your training is ready for review. Publish it to make it available to learners.':'Track your learners’ progress and manage the availability of this training.'}</p><button class="button primary" id="toggle-course">${c.status==='Draft'?'Publish training':'Move to draft'}</button>`);$('toggle-course').onclick=()=>{c.status=c.status==='Draft'?'Published':'Draft';persist();renderCourses();renderMetrics();$('dialog').close();toast('Training status updated.')}}
function persist(){localStorage.setItem('aa-courses',JSON.stringify(courses))}
$('create').onclick=()=>{showDialog('Create a training','<p>Give your team a new opportunity to learn.</p><form id="create-form"><label for="training-name">Training name</label><input id="training-name" maxlength="80" required placeholder="e.g. Creative problem solving"><label for="training-category">Category</label><select id="training-category"><option>Professional development</option><option>Compliance & security</option><option>Soft skills</option><option>Employee onboarding</option><option>Customer experience</option></select><button class="button primary" type="submit">Create training</button></form>');$('create-form').onsubmit=e=>{e.preventDefault();const name=$('training-name').value.trim();if(!name){$('training-name').setCustomValidity('Enter a training name.');$('training-name').reportValidity();return}courses.unshift({id:Date.now(),name,category:$('training-category').value,enrolled:0,progress:0,status:'Draft',lessons:0,icon:'book',color:'#f1eef9'});persist();activities.unshift({initials:'AK',name:'Alex Kumar',action:'created a new training',course:name,time:'Just now'});page=1;renderCourses();renderFeed();$('dialog').close();toast('Training created. Open it to publish when ready.')}};
const moduleData={'User management':[['Priya Sharma','Marketing · Active'],['Rahul Mehta','Engineering · Active'],['Neha Desai','Human resources · Active'],['Alex Kumar','Administrator · Active']],Assessments:[['Security final assessment','42 questions'],['Leadership skills check','18 questions'],['Communication essentials quiz','24 questions']], 'Question bank':[['Compliance & security','420 questions'],['Professional development','380 questions'],['Soft skills','260 questions'],['Employee onboarding','180 questions']], 'Content library':[['Leadership playbook.pdf','PDF · 2.4 MB'],['Security awareness recording','Video · 18 min'],['Communication workbook','PDF · 1.8 MB'],['Onboarding checklist','Document · 6 pages']], 'Reports & analytics':[['Learner participation','248 learners'],['Completed enrollments','1,437'],['Average assessment score','84.2%'],['Training completion rate','78%']], 'Role management':[['Administrator','3 members'],['Trainer','18 members'],['Learner','227 members']], 'Topic management':[['Professional development','12 topics'],['Compliance & security','8 topics'],['Soft skills','15 topics']], 'Template management':[['Standard assessment','32 uses'],['Training feedback','18 uses']], 'Evaluation sheet design':[['Skills evaluation','12 criteria'],['Training feedback','8 criteria']], 'Evaluation sheet':[['Leadership cohort','48 responses'],['New joiners','32 responses']], 'Special rights':[['Course publishing','Administrators, Trainers'],['User administration','Administrators']], 'Manage survey':[['Learner satisfaction','182 responses'],['Training needs assessment','96 responses']]};
function openModule(name){if(name==='Training management'){navigate(name);return}const entries=moduleData[name]||[];showDialog(name,`<p>${name==='Reports & analytics'?'Your workspace performance for the current reporting period.':'A snapshot of your Ability Arena workspace.'}</p><div class="module-list">${entries.map(([a,b])=>`<div>${esc(a)}<strong>${esc(b)}</strong></div>`).join('')}</div>${name==='Reports & analytics'?'<button class="button primary" id="report-export">Export training report</button>':'<p>Demo records are shown for this module.</p>'}`);if($('report-export'))$('report-export').onclick=exportCSV}
function navigate(name){activeView=name;$('breadcrumb-title').textContent=name;renderNav();document.querySelector('.sidebar').classList.remove('open');if(name==='Overview'||name==='Training management'){const overview=name==='Overview';$('overview-content').style.display=overview?'':'none';document.querySelector('.bottom-grid').classList.toggle('full-module',!overview);$('page-title').innerHTML=`${overview?'Workspace overview':'Training management'}<span class="title-dot">.</span>`;$('page-description').textContent=overview?'Welcome back, Alex. Here’s what’s happening in your arena.':'Create, publish, and track learning experiences for your team.';$('table-title').innerHTML=`${overview?'Active trainings':'All trainings'}<span class="count" id="course-count">${courses.length}</span>`;document.title=`${name} · Ability Arena`;renderCourses()}else openModule(name)}
function exportCSV(){const rows=[['Training','Category','Enrolled','Progress (%)','Status'],...filtered().map(c=>[c.name,c.category,c.enrolled,c.progress,c.status])];const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='ability-arena-training-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Training report exported.')}
$('nav').addEventListener('click',e=>{const link=e.target.closest('a');if(link){e.preventDefault();navigate(link.querySelector('span').textContent)}});$('quick-grid').addEventListener('click',e=>{const b=e.target.closest('[data-module]');if(b)openModule(b.dataset.module)});$('course-rows').addEventListener('click',e=>{const b=e.target.closest('[data-course]');if(b)courseDetail(b.dataset.course)});$('period').onchange=renderMetrics;$('search').oninput=()=>{page=1;renderCourses()};$('status-filter').onchange=()=>{page=1;renderCourses()};$('previous').onclick=()=>{page--;renderCourses()};$('next').onclick=()=>{page++;renderCourses()};$('export').onclick=exportCSV;$('view-trainings').onclick=()=>navigate('Training management');document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{chartMode=b.dataset.chart;document.querySelectorAll('[data-chart]').forEach(x=>x.classList.toggle('selected',x===b));renderChart()});$('view-activity').onclick=()=>showDialog('Workspace activity',feedHTML([...activities,{initials:'VS',name:'Vikram Singh',action:'completed an assessment',course:'Customer success fundamentals',time:'3 hours ago'},{initials:'PS',name:'Priya Sharma',action:'enrolled in a training',course:'Effective communication',time:'4 hours ago'}]));$('notifications').onclick=()=>showDialog('Notifications','<p>You have 3 new workspace updates.</p><div class="module-list"><div>12 learners joined your workspace<strong>1 hour ago</strong></div><div>Security assessment is ready for review<strong>Today</strong></div><div>Monthly learning report is available<strong>Today</strong></div></div>');$('all-modules').onclick=()=>{const modules=[...quickItems.map(x=>[x[0],x[2]]),['Role management','shield'],['Topic management','folder'],['Template management','template'],['Evaluation sheet design','quiz'],['Evaluation sheet','check'],['Special rights','shield'],['Manage survey','quiz']];showDialog('Admin modules',`<p>Everything you need to manage your learning workspace.</p><div class="module-grid">${modules.map(([name,i])=>`<button data-open-module="${name}">${icon(i)}${name}</button>`).join('')}</div>`)};$('dialog').addEventListener('click',e=>{if(e.target===$('dialog'))$('dialog').close();const b=e.target.closest('[data-open-module]');if(b){$('dialog').close();openModule(b.dataset.openModule)}});$('help').onclick=()=>showDialog('Help & support','<p>Get started with your learning workspace.</p><div class="module-list"><div>1. Create a training and choose its category.</div><div>2. Open the training and publish it.</div><div>3. Search and filter the training list.</div><div>4. Export a CSV report to share with your team.</div></div><p>This dashboard uses synthetic data. Changes to trainings are saved in this browser.</p>');$('settings').onclick=()=>{showDialog('Workspace settings','<p>Personalize your dashboard display.</p><form id="settings-form"><label for="workspace-label">Workspace name</label><input id="workspace-label" maxlength="40" required value="Ability Arena"><label for="default-period">Default reporting period</label><select id="default-period"><option value="30">Last 30 days</option><option value="7">Last 7 days</option><option value="90">Last 90 days</option></select><button class="button primary">Save settings</button></form>');$('workspace-label').value=localStorage.getItem('aa-workspace')||'Ability Arena';$('default-period').value=$('period').value;$('settings-form').onsubmit=e=>{e.preventDefault();localStorage.setItem('aa-workspace',$('workspace-label').value);localStorage.setItem('aa-period',$('default-period').value);document.querySelector('.workspace small').textContent=$('workspace-label').value;$('period').value=$('default-period').value;renderMetrics();$('dialog').close();toast('Workspace settings saved.')}};$('profile').onclick=()=>showDialog('Your profile','<p><strong>Alex Kumar</strong><br>Administrator · Ability Arena</p><div class="module-list"><div>Role<strong>Workspace administrator</strong></div><div>Access<strong>All admin modules</strong></div><div>Environment<strong>Demo workspace</strong></div></div>');$('mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');$('period').value=localStorage.getItem('aa-period')||'30';document.querySelector('.workspace small').textContent=localStorage.getItem('aa-workspace')||'Ability Arena';renderNav();renderMetrics();renderCourses();renderFeed();
